CREATE TYPE "AnalyticsRunStatus" AS ENUM ('RUNNING','SUCCEEDED','FAILED');
CREATE TYPE "AnalyticsExportStatus" AS ENUM ('PENDING','PROCESSING','READY','FAILED','EXPIRED');
CREATE TYPE "ForecastConfidence" AS ENUM ('LOW','MEDIUM','HIGH');
CREATE TABLE "product_district_daily_aggregates" ("id" TEXT NOT NULL,"product_id" TEXT NOT NULL,"district" "JharkhandDistrict" NOT NULL,"date" DATE NOT NULL,"views" INTEGER NOT NULL DEFAULT 0,"cart_adds" INTEGER NOT NULL DEFAULT 0,"units_sold" INTEGER NOT NULL DEFAULT 0,"gmv" DECIMAL(14,2) NOT NULL DEFAULT 0,"rto_count" INTEGER NOT NULL DEFAULT 0,"search_demand" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "product_district_daily_aggregates_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "product_district_daily_aggregates_product_id_district_date_key" ON "product_district_daily_aggregates"("product_id","district","date"); CREATE INDEX "product_district_daily_aggregates_district_date_idx" ON "product_district_daily_aggregates"("district","date");
CREATE TABLE "search_query_daily_aggregates" ("id" TEXT NOT NULL,"query" TEXT NOT NULL,"query_family" TEXT NOT NULL,"date" DATE NOT NULL,"district" "JharkhandDistrict","device" TEXT,"impressions" INTEGER NOT NULL DEFAULT 0,"clicks" INTEGER NOT NULL DEFAULT 0,"cart_adds" INTEGER NOT NULL DEFAULT 0,"purchases" INTEGER NOT NULL DEFAULT 0,"result_count" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "search_query_daily_aggregates_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "search_query_daily_aggregates_query_family_date_district_device_key" ON "search_query_daily_aggregates"("query_family","date","district","device"); CREATE INDEX "search_query_daily_aggregates_date_query_family_idx" ON "search_query_daily_aggregates"("date","query_family");
CREATE TABLE "variant_inventory_daily_aggregates" ("id" TEXT NOT NULL,"variant_id" TEXT NOT NULL,"date" DATE NOT NULL,"opening_stock" INTEGER NOT NULL,"closing_stock" INTEGER NOT NULL,"units_sold" INTEGER NOT NULL DEFAULT 0,"stockout_minutes" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "variant_inventory_daily_aggregates_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "variant_inventory_daily_aggregates_variant_id_date_key" ON "variant_inventory_daily_aggregates"("variant_id","date"); CREATE INDEX "variant_inventory_daily_aggregates_date_idx" ON "variant_inventory_daily_aggregates"("date");
CREATE TABLE "demand_forecast_snapshots" ("id" TEXT NOT NULL,"variant_id" TEXT NOT NULL,"forecast_7" INTEGER NOT NULL,"forecast_30" INTEGER NOT NULL,"reorder_quantity" INTEGER NOT NULL,"daily_velocity" DECIMAL(12,4) NOT NULL,"confidence" "ForecastConfidence" NOT NULL,"explanation" JSONB NOT NULL,"calculated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "demand_forecast_snapshots_pkey" PRIMARY KEY ("id")); CREATE INDEX "demand_forecast_snapshots_variant_id_calculated_at_idx" ON "demand_forecast_snapshots"("variant_id","calculated_at");
CREATE TABLE "analytics_aggregation_runs" ("id" TEXT NOT NULL,"run_key" TEXT NOT NULL,"status" "AnalyticsRunStatus" NOT NULL,"started_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completed_at" TIMESTAMP(3),"error" TEXT,"rows_processed" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "analytics_aggregation_runs_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "analytics_aggregation_runs_run_key_key" ON "analytics_aggregation_runs"("run_key"); CREATE INDEX "analytics_aggregation_runs_status_started_at_idx" ON "analytics_aggregation_runs"("status","started_at");
CREATE TABLE "analytics_export_jobs" ("id" TEXT NOT NULL,"requested_by_id" TEXT NOT NULL,"status" "AnalyticsExportStatus" NOT NULL DEFAULT 'PENDING',"filters" JSONB NOT NULL,"row_count" INTEGER,"object_key" TEXT,"error" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completed_at" TIMESTAMP(3),"expires_at" TIMESTAMP(3),CONSTRAINT "analytics_export_jobs_pkey" PRIMARY KEY ("id")); CREATE INDEX "analytics_export_jobs_requested_by_id_created_at_idx" ON "analytics_export_jobs"("requested_by_id","created_at");
